import type { GunState } from './types';

/** _-YM.PartCallTrigger resumes720; frame1 stops again after its27-frame loop. */
export function triggerMassiveCharge(gun: GunState, artAge: number) {
  const age = artAge + 1;
  // play() during playback does not restart it. Only720's leaf-only episode can
  // be coalesced this way: it has one stop, no randomness, and no child scripts.
  if (gun.mountedPlay && age < gun.mountedPlay.age + gun.mountedPlay.frames) return;
  gun.mountedPlay = { child: 'bullet_mc', age, frames: 27 };
}

export function massiveChargeFrame(gun: GunState | undefined, artAge: number) {
  const play = gun?.mountedPlay,
    elapsed = play ? artAge + 1 - play.age : -1;
  return play && elapsed >= 0 && elapsed < play.frames ? elapsed + 1 : 1;
}
import type { GunState } from '../core/types';
import type { SwfClip } from './swf-clip';

/** Lazy mounted playback shared by painting/contact, with no simulation writes. */
export class PartPlayback {
  private appliedAge = -1;
  constructor(readonly clip: SwfClip) {}
  advance(age: number, y: number, play?: GunState['mountedPlay']) {
    if (play && play.age <= age && play.age !== this.appliedAge) {
      // Materialize the stopped constructor pose before play(), then catch up.
      // Advancing directly to the render age first would lose skipped frames.
      this.clip.advance(play.age, y);
      for (const child of this.clip.children.values())
        if (child.placement.name === play.child) child.clip.play();
      this.appliedAge = play.age;
    }
    this.clip.advance(age, y);
    return this.clip;
  }
}
